"""Scaffold an ArcGIS config actor: writes actors/<name>/impl.py calling lib.arcgis_actor
with the config in actors/<name>/config.json. Re-run after editing config.json."""
import json, pathlib, sys
ROOT = pathlib.Path(__file__).resolve().parent.parent
for n in sys.argv[1:]:
    d = ROOT / "actors" / n
    cfg = json.loads((d / "config.json").read_text())
    (d / "impl.py").write_text(
        "import json\n\nfrom .lib import arcgis_actor\n\n# generated by scripts/new.py from config.json\n"
        "CONFIG = json.loads(" + repr(json.dumps(cfg)) + ")\n\n\nasync def run(inp, client, emit):\n    await arcgis_actor(CONFIG, inp, client, emit)\n"
    )
